# views.py - Django REST Framework template rendering service
from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework.permissions import IsAuthenticated
from django.template import Template, Context
from django.conf import settings
import boto3
import json
import logging

logger = logging.getLogger(__name__)


class NotificationTemplateView(APIView):
    """Renders notification templates with user-provided variables.
    Used by internal microservices to generate email/SMS content."""
    permission_classes = [IsAuthenticated]

    def post(self, request):
        template_str = request.data.get('template', '')
        context_vars = request.data.get('variables', {})

        if not template_str:
            return Response({'error': 'template is required'}, status=400)

        # Validate context variables are simple types
        for key, value in context_vars.items():
            if not isinstance(value, (str, int, float, bool)):
                return Response({'error': f'Variable {key} must be a simple type'}, status=400)

        try:
            # Render the Django template with provided context
            tmpl = Template(template_str)
            ctx = Context(context_vars)
            rendered = tmpl.render(ctx)
            return Response({'rendered': rendered})
        except Exception as e:
            logger.error(f"Template rendering failed: {e}")
            return Response({'error': 'Template rendering failed'}, status=500)


class SecretFetchView(APIView):
    """Fetches secrets from AWS Secrets Manager for template variable injection."""
    permission_classes = [IsAuthenticated]

    def get(self, request):
        secret_name = request.query_params.get('name', '')
        if not secret_name:
            return Response({'error': 'name parameter required'}, status=400)

        # Only allow fetching from our namespace
        if not secret_name.startswith('notifications/'):
            return Response({'error': 'Access denied: invalid secret namespace'}, status=403)

        try:
            client = boto3.client('secretsmanager', region_name=settings.AWS_REGION)
            response = client.get_secret_value(SecretId=secret_name)
            secret_data = json.loads(response['SecretString'])
            return Response({'secret': secret_data})
        except client.exceptions.ResourceNotFoundException:
            return Response({'error': 'Secret not found'}, status=404)
        except Exception as e:
            logger.error(f"Secret fetch failed: {e}")
            return Response({'error': 'Failed to fetch secret'}, status=500)


class TemplateDebugView(APIView):
    """Debug endpoint for template syntax validation (dev/staging only)."""
    permission_classes = [IsAuthenticated]

    def post(self, request):
        if not settings.DEBUG:
            return Response({'error': 'Not available in production'}, status=403)

        template_str = request.data.get('template', '')
        try:
            tmpl = Template(template_str)
            # Return AST node info for debugging
            nodes = []
            for node in tmpl.nodelist:
                nodes.append({
                    'type': type(node).__name__,
                    'token': str(node.token) if hasattr(node, 'token') else None
                })
            return Response({'valid': True, 'nodes': nodes})
        except Exception as e:
            return Response({'valid': False, 'error': str(e)})


